WITH lines AS (SELECT id, service, host, log_ts, level, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) t AS attr_key, attr_value), base AS (SELECT *, UPPER(attr_key) attr_key_upper, COALESCE(attr_key, 'OTHER') resolved_attr_key FROM lines WHERE attr_key IS NOT NULL), enriched AS (SELECT id, service, host, log_ts, level, status_code, attr_key, attr_value, attr_key_upper, resolved_attr_key, LAG(status_code, 2, 0) OVER (PARTITION BY level ORDER BY log_ts ASC, id ASC, attr_key ASC) prev_status_code, LAST_VALUE(attr_key) IGNORE NULLS OVER w_hist last_known_attr_key, RANK() OVER w_grp status_code_rank FROM base WINDOW w_hist AS (PARTITION BY attr_key ORDER BY log_ts ASC, id ASC, attr_key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_grp AS (PARTITION BY host ORDER BY status_code ASC)) SELECT id, service, host, log_ts, level, attr_key, attr_key_upper, prev_status_code, last_known_attr_key FROM enriched;
